CREATE FUNCTION public.enforce_home_church_is_a_church() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.home_church_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM artists WHERE id = NEW.home_church_id AND kind = 'church') THEN
        RAISE EXCEPTION
            'artist % cannot belong to %: that is not a church profile', NEW.id, NEW.home_church_id
            USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.kind = 'church' AND NEW.kind <> 'church'
       AND EXISTS (SELECT 1 FROM artists WHERE home_church_id = NEW.id) THEN
        RAISE EXCEPTION
            'artist % is home to other profiles and must stay a church', NEW.id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION public.enforce_publication_requires_granted_license() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    licence_state TEXT;
    licence_expiry TIMESTAMPTZ;
BEGIN
    IF NEW.status <> 'published' THEN
        RETURN NEW;
    END IF;
    IF NEW.license_id IS NULL THEN
        RAISE EXCEPTION
            'media_item % cannot be published: no licence attached', NEW.id
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT consent_status, expires_at INTO licence_state, licence_expiry
    FROM licenses WHERE id = NEW.license_id;
    IF licence_state IS DISTINCT FROM 'granted' THEN
        RAISE EXCEPTION
            'media_item % cannot be published: licence % is %', NEW.id, NEW.license_id, licence_state
            USING ERRCODE = 'check_violation';
    END IF;
    IF licence_expiry IS NOT NULL AND licence_expiry <= now() THEN
        RAISE EXCEPTION
            'media_item % cannot be published: licence % expired at %', NEW.id, NEW.license_id, licence_expiry
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;
